using System.Reflection;using System.Text.Json;using ValveKeyValue;using ValveKeyValue.KeyValues3;using ValveResourceFormat;using ValveResourceFormat.ResourceTypes;using ValveResourceFormat.Serialization.KeyValues;
internal static class WildlifeMaterialTests {
