  void Case(string name,bool sameExpression,bool expectRepair){
   var root=KVObject.Collection();root["m_materialName"]=new KVObject(name);root["m_shaderName"]=new KVObject("global_lit_simple.vfx");foreach(var key in new[]{"m_intParams","m_floatParams","m_vectorParams","m_textureParams","m_dynamicParams","m_dynamicTextureParams","m_intAttributes","m_floatAttributes","m_vectorAttributes","m_textureAttributes","m_stringAttributes","m_renderAttributesUsed"})root[key]=KVObject.Array();
   const string atlas="harlord/materials/models/props_wildlife/wildlife001_color_psd_4b61b7d3.vtex";var texture=KVObject.Collection();texture["m_name"]=new KVObject("g_tColor");texture["m_pValue"]=new KVObject(atlas){Flag=KVFlag.Resource};root["m_textureParams"].Add(texture);
   byte[] fadeout=[0x19,0xfb,0x85,0x60,0x27,0];var scalar=KVObject.Collection();scalar["m_name"]=new KVObject("g_flAlphaTestReference");scalar["m_value"]=KVObject.Blob(fadeout);root["m_dynamicParams"].Add(scalar);var dynamicTexture=KVObject.Collection();dynamicTexture["m_name"]=new KVObject("g_tColor");dynamicTexture["m_value"]=KVObject.Blob(sameExpression?fadeout:[0x19,1,2,3,4,0]);root["m_dynamicTextureParams"].Add(dynamicTexture);
   string input=Path.Combine(dir,"wildlife-"+Guid.NewGuid().ToString("N")+".vmat_c"),output=input+"-out.vmat_c";var block=new BinaryKV3(root,new KV3ID("generic",new Guid("7412167c-06e9-4698-aff2-e63eb59037e7"))){Resource=new Resource(),SerializationVersion=5};using var payload=new MemoryStream();block.Serialize(payload);using(var stream=File.Create(input))using(var w=new BinaryWriter(stream)){w.Write((uint)(28+payload.Length));w.Write((ushort)12);w.Write((ushort)1);w.Write(8u);w.Write(1u);w.Write(System.Text.Encoding.ASCII.GetBytes("DATA"));w.Write(8u);w.Write((uint)payload.Length);w.Write(payload.ToArray());}
   var manifest=input+".json";File.WriteAllText(manifest,JsonSerializer.Serialize(new{paths=new Dictionary<string,string>(),files=new[]{new{input,output}}}));assembly.GetType("ResourceRelocator")!.GetMethod("Run")!.Invoke(null,new object[]{manifest});using var check=new Resource{FileName=output};check.Read(output);var material=(Material)check.DataBlock!;Check(material.Data["m_dynamicTextureParams"].Count==(expectRepair?0:1),"Wrong dynamic texture repair scope");Check(material.TextureParams["g_tColor"]==atlas,"Static atlas changed");Check(material.Data["m_dynamicParams"][0].GetArray<byte>("m_value").SequenceEqual(fadeout),"Scalar transparency changed");Check(material.ShaderName=="global_lit_simple.vfx","Shader changed");var repeat=(bool)assembly.GetType("WildlifeMaterial")!.GetMethod("Repair",BindingFlags.NonPublic|BindingFlags.Static)!.Invoke(null,new object[]{material})!;Check(!repeat,"Repair is not idempotent");
  }
  Case("harlord/materials/models/props_wildlife/wildlife001.vmat",true,true);Case("materials/models/props_wildlife/wildlife001.vmat",true,true);Case("materials/unrelated.vmat",true,false);Case("harlord/materials/models/props_wildlife/wildlife001.vmat",false,false);Console.WriteLine("Wildlife material tests passed: invalid texture expression, scalar alpha, static atlas, unrelated materials and idempotence.");
